//! Known answers for the RFC 7919 FFDHE groups ffdhe2048 / ffdhe3072, computed with Python `pow()`
//! (an implementation independent of `montint`). Exponents are fixed (SHA-256 of a label),
//! `lz_*` is a pair whose shared secret starts with a zero byte (RFC 8446 §7.4.1: kept).
//! Regenerate with the script described in the commit message; values are plain constants.

const std = @import("std");

/// `testkit.hex.bytes` with a raised comptime branch quota (384-byte vectors).
fn hx(comptime n: usize, comptime s: *const [2 * n:0]u8) [n]u8 {
    @setEvalBranchQuota(200_000);
    var out: [n]u8 = undefined;
    _ = std.fmt.hexToBytes(&out, s) catch @compileError("bad hex literal");
    return out;
}

pub const ffdhe2048_xa = hx(29, "006120f2b1d5f3d62f1000e69fbf6a7bb6f67a40256ff768b15963f31f");
pub const ffdhe2048_ya = hx(256, "");
pub const ffdhe2048_xb = hx(29, "010d6e2c88bd89a9e9eb03508dd7cf63c47375987bc70f86d7eeb6bbac");
pub const ffdhe2048_yb = hx(256, "");
pub const ffdhe2048_z = hx(256, "");
pub const ffdhe2048_xmax = hx(29, "01ffffffffffffffffffffffffffffffffffffffffffffffffffffffff");
pub const ffdhe2048_ymax = hx(256, "");
pub const ffdhe2048_lz_xc = hx(29, "003ae565fefddb5872d6860e885c209df5e8173f65f6e890089c8a4f4c");
pub const ffdhe2048_lz_yc = hx(256, "");
pub const ffdhe2048_lz_ys = hx(256, "");
pub const ffdhe2048_lz_z = hx(256, "");

